INSERT INTO "Habilidade" ("id", "codigo", "nome", "descricao", "classe", "tipo", "elemento", "icone", "custo", "cooldown", "dano", "alcance", "raio", "duracao", "efeito", "potencia", "nivelReq", "ultimate", "aprendizado", "atualizadoEm") VALUES
('hab_chicote_de_espinhos', 'chicote_de_espinhos', 'Chicote de Espinhos', 'Forma humana. Um chicote de espinhos em linha reta que fere e envenena o primeiro inimigo.', 'DRUIDA', 'SKILLSHOT', 'NATUREZA', 'minecraft:vine', 10, 2.5, 5, 16, 0, 0, '', 0, 1, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_forma_lobo', 'forma_lobo', 'Forma de Lobo', 'Vira lobo por até 45 s: +25% de velocidade e garras fortes no lugar da arma, mas apanha 10% mais. A barra troca para as habilidades de lobo. Usar de novo volta à forma humana.', 'DRUIDA', 'BUFF', 'NATUREZA', 'minecraft:bone', 20, 8, 0, 0, 0, 45, 'frx:forma', 1, 2, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_rejuvenescer', 'rejuvenescer', 'Rejuvenescer', 'Forma humana. Cura um pouco o aliado na mira (ou você) e deixa Regeneração II por 8 s.', 'DRUIDA', 'ALVO', 'NATUREZA', 'minecraft:glow_berries', 25, 9, -3, 14, 0, 8, 'minecraft:regeneration', 2, 3, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_lobo_dilacerar', 'lobo_dilacerar', 'Dilacerar', 'Forma de lobo. Uma mordida que fere e faz o alvo sangrar por 5 s.', 'DRUIDA', 'ALVO', 'FISICO', 'minecraft:flint', 15, 7, 5, 4.5, 0, 5, 'frx:sangria', 0, 4, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_raizes_presas', 'raizes_presas', 'Raízes Presas', 'Forma humana. Planta raízes no chão mirado: quem pisar leva dano e fica preso por 4 s. Ficam 45 s armadas, no máximo duas.', 'DRUIDA', 'AREA', 'NATUREZA', 'minecraft:hanging_roots', 30, 18, 4, 12, 2.5, 4, 'frx:armadilha', 0, 6, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_lobo_bote', 'lobo_bote', 'Bote', 'Forma de lobo. Salta na direção da mira e fere quem estiver em volta de onde cair.', 'DRUIDA', 'MOBILIDADE', 'FISICO', 'minecraft:rabbit_foot', 20, 9, 7, 10, 3, 0, 'frx:salto', 0, 8, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_forma_urso', 'forma_urso', 'Forma de Urso', 'Vira urso por até 45 s: +25% de vida, 15% menos dano recebido e quase não é empurrado, mas fica 10% mais lento e as garras batem menos que as do lobo. Usar de novo volta à forma humana.', 'DRUIDA', 'BUFF', 'NATUREZA', 'minecraft:honeycomb', 20, 8, 0, 0, 0, 45, 'frx:forma', 2, 10, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_urso_patada', 'urso_patada', 'Patada', 'Forma de urso. Uma patada em leque que fere e empurra todos à frente.', 'DRUIDA', 'AREA', 'FISICO', 'minecraft:brown_dye', 20, 6, 7, 5, 0, 0, 'frx:leque', 0, 10, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_urso_rugido', 'urso_rugido', 'Rugido', 'Forma de urso. Os monstros em volta largam os aliados e vêm para você, que ganha Resistência II por 8 s.', 'DRUIDA', 'AREA', 'FISICO', 'minecraft:salmon', 25, 18, 2, 0, 8, 8, 'frx:provocar', 2, 12, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_pele_de_casca', 'pele_de_casca', 'Pele de Casca', 'Forma humana. Você e os aliados a até 6 blocos ganham Resistência I por 8 s.', 'DRUIDA', 'BUFF', 'NATUREZA', 'minecraft:oak_log', 30, 24, 0, 0, 6, 8, 'minecraft:resistance', 1, 14, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_lobo_uivo', 'lobo_uivo', 'Uivo', 'Forma de lobo. Por 8 s, 30% do dano que você causa volta como vida.', 'DRUIDA', 'BUFF', 'FISICO', 'minecraft:goat_horn', 25, 25, 0, 0, 0, 8, 'frx:vampirismo', 3, 16, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_urso_hibernar', 'urso_hibernar', 'Hibernar', 'Forma de urso. Por 4 s (mais lento) recupera vida e mana e limpa veneno, definhamento, fraqueza, cegueira e fogo.', 'DRUIDA', 'BUFF', 'NATUREZA', 'minecraft:sweet_berries', 20, 40, -4, 0, 0, 4, 'frx:meditar', 3, 18, false, 'ITEM', CURRENT_TIMESTAMP),
('hab_forma_ave', 'forma_ave', 'Forma de Ave', 'Vira ave por até 15 s e voa. Na forma de ave você quase não fere e apanha 25% mais: serve para atravessar, fugir e explorar. Usar de novo volta à forma humana.', 'DRUIDA', 'BUFF', 'NATUREZA', 'minecraft:feather', 30, 45, 0, 0, 0, 15, 'frx:forma', 3, 20, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_ira_da_floresta', 'ira_da_floresta', 'Ira da Floresta', 'Em qualquer forma. Por 8 s a mata cresce em volta de você: a cada segundo os inimigos a até 7 blocos levam dano e ficam quase parados, e os aliados curam.', 'DRUIDA', 'AREA', 'NATUREZA', 'minecraft:oak_sapling', 100, 120, 7, 0, 7, 8, 'frx:floresta', 2, 25, true, 'NIVEL', CURRENT_TIMESTAMP)
